const prose = document.getElementById('prose-acronyms');
const main = document.getElementById('main-content');
if (!prose || !main) return false;

const isEnabled = document.getElementById('ai4a11y-abbr-styles') !== null;
if (!isEnabled) return true;

// Ensure page does not have horizontal scrolling
const hasHorizontalScroll = document.documentElement.scrollWidth > window.innerWidth;
if (hasHorizontalScroll) return false;

// Verify that abbr elements are inline and respect container boundary
const abbrs = prose.querySelectorAll('abbr.ai4a11y-abbr');
if (abbrs.length === 0) return false;
for (const a of abbrs) {
  const rect = a.getBoundingClientRect();
  if (rect.right > window.innerWidth) return false;
}

return true;

